\begin{theorem}\label{Landau}
Let $f$ be a continuous fuzzy-number-valued function on $[0,\infty)$. If there exist negative constant fuzzy number $u$ and a real number $x_0\geq 0$ such that
\begin{eqnarray}\label{one}
xf(x)\succeq u \quad \textrm{for}\quad x>x_0,
\end{eqnarray}
then fuzzy-number-valued function $s(t)=\int\limits_{0}^{t}f(x)dx$ is slowly decreasing.
\end{theorem}
\begin{proof}
Let $ xf(x)\succeq u$ be satisfied under the given conditions on $u$ and $x_0$ in the theorem. Then for $x>x_0$ we have
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq u^-_{\alpha}\geq u^-_{0}\qquad ,\qquad xf_{\alpha}^+(x)\geq u^+_{\alpha}\geq u^+_{1}\geq u^-_{0}.
\end{eqnarray*}
For the sake of simplicity let take $u^-_{0}=-H$ where $H> 0$. Then
\begin{eqnarray*}
xf_{\alpha}^-(x)\geq -H \Rightarrow f_{\alpha}^-(x)\geq -\frac{H}{x}\quad ,\quad
xf_{\alpha}^+(x)\geq -H \Rightarrow f_{\alpha}^+(x)\geq -\frac{H}{x}
\end{eqnarray*}
are satisfied. Then for $x_0< t<x\leq \lambda t$ when $\lambda>1$, we have
\begin{eqnarray*}
s_{\alpha}^-(x)-s_{\alpha}^-(t)=\int_t^xf_{\alpha}^-(u)du\geq -H\int_t^x\frac{du}{u}=-H\ln\frac{x}{t}\geq -H\ln \lambda
\end{eqnarray*}
and
\begin{eqnarray*}
s_{\alpha}^+(x)-s_{\alpha}^+(t)=\int_t^xf_{\alpha}^+(u)du\geq -H\int_t^x\frac{du}{u}=-H\ln\frac{x}{t}\geq -H\ln \lambda.
\end{eqnarray*}
Choosing $\lambda =e^{\varepsilon/H}$, we get the inequalities
\begin{eqnarray*}
s_{\alpha}^-(x)\geq s_{\alpha}^-(t)-\varepsilon\qquad ,\qquad
s_{\alpha}^+(x)\geq s_{\alpha}^+(t)-\varepsilon
\end{eqnarray*}
and then $s(x)\succeq s(t)-\overline{\varepsilon}$ holds whenever $x_0< t<x\leq \lambda t$.
\end{proof}
